import {createBillingUI} from './billing-ui.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.documentElement.dataset.palette=localStorage.getItem('swanlab-demo4-palette')==='neutral-purple'?'neutral-purple':'warm-purple';
const KEY='swanlab-project-v042-demo3';let s;try{s=JSON.parse(localStorage.getItem(KEY))||M.seed()}catch{s=M.seed()}
let ui={search:'',scope:'all',tag:'all',sort:'date',view:'list',tab:'active',dev:false,public:false,sidebarCollapsed:true};
M.upgradePrototypeState(s);
// Normalize persisted demo data to the English project copy.
const projectCopy={
 'Qwen3 · 指令微调':['Qwen3 · Instruction Tuning','Explore lightweight training with traceable experiments.'],
 '多模态检索 · 评估集':['Multimodal Retrieval · Evaluation Set','Unified text and image representations for cross-modal retrieval.'],
 'Research / 未发布模型':['Research / Unreleased Model','An internal research project protected for specific members.'],
 'ImageNet / ResNet-50':['ImageNet / ResNet-50','Image classification baseline comparing learning rates and augmentation strategies.']
};
for(const org of s.orgs||[])for(const project of org.projects||[]){const copy=projectCopy[project.name];if(copy){project.name=copy[0];project.desc=copy[1];}}

const route=new URLSearchParams(location.search);if(!route.has('view')&&!route.has('org')&&!s.loggedOut&&!s.registration)s.page='orgOverview';if(route.get('view')==='overview')s.page='orgOverview';if(route.get('view')==='register')s.page='auth';if(route.get('view')==='account-settings')s.page='account';if(route.get('view')==='projects')s.page='projects';if(route.get('view')==='organization-settings')s.page='settings';if(['usage','billing'].includes(route.get('view')))s.page=route.get('view');if(route.get('view')==='members'||s.page==='rolePermissions')s.page='members';if(route.has('org')&&s.orgs.some(o=>o.id===route.get('org'))){s.orgId=route.get('org');s.projectId=route.get('project')||route.get('public');s.page='project';ui.public=route.has('public');}

const icon=(name)=>`<svg class="lucide lucide-${iconNames[name]||iconNames.project}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${iconNodes[name]||iconNodes.project}</svg>`;
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const badge=(text,cls='')=>`<span class="badge ${cls}">${text}</span>`;
const fmt=n=>(n/1e9).toLocaleString('en',{maximumFractionDigits:2});
const o=()=>M.currentOrg(s), can=(a,p)=>M.canPerformAction(s,a,p), visible=()=>o().projects.filter(p=>M.canAccessProject(s,p));
const scopes={MEMBERS:'指定成员',SPACE:'组织',PUBLIC_READONLY:'公开'};
const roles=['Owner','管理员','贡献者','查看者'];
const opt=(v,t,sel)=>`<option value="${esc(v)}" ${v===sel?'selected':''}>${esc(t)}</option>`;
const options=(arr,sel)=>arr.map(v=>opt(v,v,sel)).join('');
const billingUI=createBillingUI({state:()=>s,model:M,esc,btn,badge,modal,close,render,save,toast});
const groupUI=createPermissionGroupsUI({state:()=>s,org:o,model:M,esc,btn,badge,head,empty,modal,close,render,save,toast,formError,icon,date:formatMemberDate});
function save(){localStorage.setItem(KEY,JSON.stringify(s))}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(ui.toast);ui.toast=setTimeout(()=>$('#toast').style.display='none',5000)}
function run(fn){try{fn();save();render()}catch(e){render();toast(e.message)}}
function head(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1></div>${action}</div>`}
function scopeBadge(p){return badge(icon(p.scope==='PUBLIC_READONLY'?'globe':p.scope==='MEMBERS'?'lock':'users')+scopes[p.scope],'scope-badge')}
function empty(title,desc,action=''){return `<div class="empty">${icon('project')}<h3>${title}</h3><p>${desc}</p>${action}</div>`}
const accountPages=['account','security','developer','myOrganizations'];
const orgPages=['settings','rolePermissions','members','permissionGroups','permissionGroup','projectAdmin','usage','billing','trash'];
function nav(page,text,ic){return `<button data-action="nav" data-page="${page}" title="${text}" aria-label="${text}" class="${(s.page===page||page==='permissionGroups'&&s.page==='permissionGroup'||text==='组织管理'&&orgPages.includes(s.page))?'active':''}">${icon(ic)}<span class="nav-label">${text}</span>${page==='projects'?`<span class="count">${visible().length}</span>`:''}</button>`}
let lastRenderedSection;
function render(){if(s.page!=='billing'||!M.isOwner(s))billingUI.invalidate();const section=orgPages.includes(s.page)?'organization':s.page;const routeChanged=lastRenderedSection!==section;lastRenderedSection=section;applyTheme();if(new URLSearchParams(location.search).get('preview')==='login'){renderAuth();return;}if(s.registration){renderOnboarding();return;}if(s.page==='createProject'){renderProjectCreatePage();return;}M.upgradePrototypeState(s);
// Normalize persisted demo data to the English project copy.
const projectCopy={
 'Qwen3 · 指令微调':['Qwen3 · Instruction Tuning','Explore lightweight training with traceable experiments.'],
 '多模态检索 · 评估集':['Multimodal Retrieval · Evaluation Set','Unified text and image representations for cross-modal retrieval.'],
 'Research / 未发布模型':['Research / Unreleased Model','An internal research project protected for specific members.'],
 'ImageNet / ResNet-50':['ImageNet / ResNet-50','Image classification baseline comparing learning rates and augmentation strategies.']
};
for(const org of s.orgs||[])for(const project of org.projects||[]){const copy=projectCopy[project.name];if(copy){project.name=copy[0];project.desc=copy[1];}}
ui.view=s.profiles[s.user]?.projectView==='cards'?'cards':'list';M.rememberAccount(s);M.expireInvites(s);M.finalizeMigrationTrial(s);save();if(ui.public){renderPublic();return}if(s.loggedOut||s.page==='auth'){renderAuth();return}
 const org=o(),m=M.member(s),ratio=M.checkCapacity(org),active=org.members.filter(m=>m.status==='active').length;
 renderPage(`<div class="shell ${ui.sidebarCollapsed?'sidebar-collapsed':'sidebar-expanded'}"><aside class="sidebar"><div class="brand" title="SwanLab"><button class="sidebar-toggle" data-action="sidebarToggle" aria-label="${ui.sidebarCollapsed?'展开侧边栏':'收起侧边栏'}" title="${ui.sidebarCollapsed?'展开侧边栏':'收起侧边栏'}">${icon('chevron')}</button><a class="brand-home" href="https://swanlab.cn/home" target="_blank" rel="noopener noreferrer" aria-label="SwanLab 官网（新标签页打开）" title="SwanLab 官网"><img src="logo.png" alt="" width="28" height="28"></a>SwanLab<sup>LAB</sup></div><nav class="navgroup">${nav('projects','所有项目','grid')}</nav>${M.isManager(s)?`<nav class="navgroup">${nav('settings','组织管理','settings')}</nav>`:''}<div class="sidebottom">${can('usage')&&!['profile',...accountPages].includes(s.page)?`<div class="capacitymini"><div class="row between"><span>组织存储</span><b>${Math.round(ratio.ratio*100)}%</b></div><div class="bar ${ratio.status}"><i style="width:${Math.min(100,ratio.ratio*100)}%"></i></div><p style="margin:9px 0">${fmt(org.used)} / ${fmt(org.capacity)} GB</p>${btn('查看用量','nav','small ghost','data-page="usage"')}</div>`:''}<button class="account" id="account-trigger" data-action="accountMenu" aria-label="打开账号菜单" title="账户菜单" aria-haspopup="dialog" aria-expanded="false" aria-controls="account-menu"><span class="avatar owner">${esc((s.profiles[s.user]?.name||m?.name)?.slice(-2)||'访客')}</span><span style="text-align:left;flex:1">${esc(s.profiles[s.user]?.name||m?.name||'受限账号')}<small style="display:block;font-size:10px">${m?.role||'无有效组织成员身份'}</small></span>${icon('chevron')}</button></div></aside><main class="main">${capacityAlert()}<header class="topbar"><nav class="crumb" aria-label="面包屑">${s.page==='profile'||accountPages.includes(s.page)?`${btn(accountPages.includes(s.page)?'账户设置':'个人主页','nav','crumb-link',`data-page="${accountPages.includes(s.page)?'account':'profile'}"`)}${accountPages.includes(s.page)?'<span>/</span><span>'+({account:'常规',security:'账户与许可证',developer:'开发者设置',myOrganizations:'我的组织'})[s.page]+'</span>':''}`:`${organizationCrumb(org)}<span>/</span>${s.page==='project'?btn('所有项目','nav','crumb-link','data-page="projects"')+'<span>/</span>':''}${s.page==='permissionGroup'?groupUI.breadcrumb():`<b>${({orgOverview:'组织概览',projects:'所有项目',project:'实验',members:'成员管理',permissionGroups:'权限组',permissionGroup:'权限组详情',rolePermissions:'角色与权限',usage:'用量',billing:'账单',projectAdmin:'项目管理',trash:'回收站',security:'账户与许可证',developer:'开发者设置',migration:'迁移与过渡',settings:'组织设置'})[s.page]||'所有项目'}</b>`}`}</nav><div class="row topbar-actions">${btn(icon('search')+'<span>搜索…</span><kbd>'+(navigator.platform.includes('Mac')?'⌘ K':'Ctrl K')+'</kbd>','command','global-search','aria-label="全局搜索" title="搜索项目、组织或页面"')}<nav class="header-resources" aria-label="快捷入口"><a href="https://dev.powerducker.com/benchmarks" target="_blank" rel="noopener noreferrer" aria-label="基线社区" title="基线社区">${icon('globe')}</a><a href="https://docs.swanlab.cn/" target="_blank" rel="noopener noreferrer" aria-label="SwanLab 官方文档" title="SwanLab 官方文档">${icon('book')}</a>${btn(icon('bolt'),'create','header-icon','aria-label="快速开始：创建新项目" title="快速开始：创建新项目" '+(can('create')?'':'disabled'))}<a href="https://github.com/SwanHubX/SwanLab" target="_blank" rel="noopener noreferrer" aria-label="SwanLab GitHub" title="SwanLab GitHub">${icon('github')}</a></nav></div></header><div class="content page-${s.page}${routeChanged?' d4-route-enter':''}" id="content">${ui.loading?'<div class="skeleton" aria-label="正在加载" role="status"><div></div><div></div><div></div><p>正在加载组织项目…</p></div>':s.regionFailure&&!['profile',...accountPages].includes(s.page)&&(!s.failureRegion||s.failureRegion===o().region)?empty('目标区域暂不可用',`${esc(org.name)} · ${org.region}。身份与权限保持不变，可切换其他组织或重试。`,btn('重试区域连接','retry','primary')):s.requestFailure?empty('数据读取失败','筛选和输入已保留，重试后继续。',btn('重新加载','retry','primary')):pageContent()}</div></main></div>${btn(icon('code')+' 验证面板','dev','devbutton')}${ui.dev?devPanel():''}${accountMenuMarkup()}${orgMenuMarkup()}`);
 bind();}
function banner(){return '';}
function organizationCrumb(org){return `<div class="breadcrumb-org"><button class="crumb-link org-overview-link" data-action="nav" data-page="orgOverview" aria-label="打开组织概览"><span class="org-avatar-small">${org.avatar?`<img src="${esc(org.avatar)}" alt="">`:esc(org.name.slice(0,1))}</span><span class="org-crumb-name">${esc(org.name)}</span></button><span class="badge org-plan">${org.paid?'TEAM':'FREE'}</span><button id="org-menu-trigger" class="crumb-org-switch" data-action="orgMenu" aria-label="切换或创建组织" title="切换或创建组织" aria-haspopup="dialog" aria-expanded="false" aria-controls="org-menu">${icon('chevron')}</button></div>`;}
function capacityAlert(){if(['profile',...accountPages].includes(s.page))return '';const r=M.checkCapacity(o()),key=o().id+':'+r.status+':'+o().used+':'+o().capacity;if(r.status==='normal'||ui.dismissedCapacityAlert===key)return '';return `<div class="capacity-alert ${r.status}" role="${r.status==='full'?'alert':'status'}"><span class="capacity-alert-symbol" aria-hidden="true">!</span><div><strong>${r.status==='full'?'组织存储容量已满':'组织存储容量即将用尽'}</strong><span class="alert-separator">·</span><span>已使用 ${fmt(o().used)} / ${fmt(o().capacity)} GB${r.status==='full'?'，新增实验和文件上传已暂停':''}</span>${can('usage')?(M.isOwner(s)?btn('管理容量','nav','alert-link','data-page="usage"'):'<span>，联系组织 Owner 升级。</span>'):'<span>，请联系 Owner 扩容。</span>'}</div>${btn(icon('close'),'dismissCapacityAlert','alert-close','aria-label="关闭容量提醒"')}</div>`;}
function pageContent(){const body=rawPageContent();return accountPages.includes(s.page)||orgPages.includes(s.page)?settingsLayout(body):body;}
function orgNavigation(){return nav('settings','常规','settings')+nav('members','成员管理','users')+nav('permissionGroups','权限组','lock')+nav('projectAdmin','项目管理','project')+nav('usage','用量','chart')+(can('billing')?nav('billing','账单','billing'):'')+nav('trash','回收站','trash');}
function settingsLayout(body){body=body.replace(/<h1>/g,'<h2 class="section-title">').replace(/<\/h1>/g,'</h2>');const personal=accountPages.includes(s.page);if(!personal)return `<div class="settings-layout organization-layout"><nav class="settings-nav" aria-label="组织设置导航"><h3>组织设置</h3>${orgNavigation()}</nav><div class="settings-body organization-content page-${s.page}">${body}</div></div>`;return `<div class="settings-layout organization-layout account-layout"><nav class="settings-nav" aria-label="账户设置导航"><h3>账户设置</h3>${nav('account','常规','user')}${nav('security','账户与许可证','lock')}${nav('developer','开发者设置','code')}${nav('myOrganizations','我的组织','users')}</nav><div class="settings-body organization-content account-content">${body}</div></div>`;}
function rawPageContent(){switch(s.page){case'myOrganizations':return myOrganizationsPage();case'rolePermissions':return rolePermissionsPage();case'orgOverview':return orgOverviewPage();case'security':return securityPage();case'developer':return developerPage();case'permissionGroups':return groupUI.page();case'permissionGroup':return groupUI.page(true);case'projectAdmin':return adminProjectsPage();case'trash':return trashPage();case'projects':return projectsPage();case'project':return projectPage();case'members':return membersPage();case'usage':return usagePage();case'billing':return billingPage();case'migration':s.page='members';ui.tab='legacy';return membersPage();case'settings':return settingsPage();case'account':return accountPage();case'profile':return profilePage();case'categories':s.page='projects';return projectsPage();default:s.page='projects';return projectsPage()}}
function isPinned(p){return (s.profiles[s.user]?.pinned||[]).includes(p.id)}
function filtered(){return visible().filter(p=>(!ui.search||(p.name+' '+(p.desc||'')+' '+p.tags.join(' ')).toLowerCase().includes(ui.search.toLowerCase()))&&(matchesFilter(ui.scope,p.scope))&&(matchesFilter(ui.tag,p.tags))).sort((a,b)=>(ui.sort==='name'?a.name.localeCompare(b.name,'zh'):ui.sort==='size'?b.bytes-a.bytes:(b.lastExperimentAt||'').localeCompare(a.lastExperimentAt||'')));}
function projectsPage(){let ps=filtered();let ts=[...new Set(visible().flatMap(p=>p.tags))];return `<h1 class="projects-page-title">所有项目 <span class="project-total" aria-label="${ps.length} 个项目">${ps.length}</span></h1>`+banner()+`<div class="toolbar projects-toolbar"><div class="search">${icon('search')}<input id="search" type="search" aria-label="搜索项目名称、描述和标签" placeholder="搜索名称、描述、标签…" value="${esc(ui.search)}"></div><select id="scope-filter" class="filter-select ${ui.scope==='all'?'is-empty':''}" aria-label="项目范围">${opt('all','所有可见范围',ui.scope)}${Object.entries(scopes).map(([k,v])=>opt(k,v,ui.scope)).join('')}</select><select id="tag-filter" class="filter-select ${ui.tag==='all'?'is-empty':''}" aria-label="标签">${opt('all','所有分类',ui.tag)}${options(ts,ui.tag)}</select><select id="sort" class="filter-select ${ui.sort==='date'?'is-empty':''}" aria-label="项目排序">${opt('date','最近实验更新',ui.sort)}${opt('name','名称排序',ui.sort)}${opt('size','存储占用',ui.sort)}</select>${(ui.search||ui.scope!=='all'||ui.tag!=='all'||ui.sort!=='date')?btn('重置筛选项','resetProjectFilters','small ghost reset-project-filters'):''}<div class="spacer"></div><div class="segments">${btn(icon('list'),'view',ui.view==='list'?'selected':'',`data-value="list" aria-label="列表视图" aria-pressed="${ui.view==='list'}"`)}${btn(icon('grid'),'view',ui.view==='cards'?'selected':'',`data-value="cards" aria-label="卡片视图" aria-pressed="${ui.view==='cards'}"`)}</div><div class="projects-primary-actions">${can('create')?btn(icon('plus')+' 创建项目','create','primary'):''}</div></div><section id="project-results">${ps.length?ui.view==='cards'?`<div class="grid">${ps.map(p=>card(p)).join('')}</div>`:projectTable(ps):empty(visible().length?'没有匹配的项目':'从第一个项目开始',visible().length?'试试其他关键词，或清除当前筛选。':'项目将归属于当前组织，你可以按实验方向整理它们。',btn(visible().length?'清除筛选':'创建项目',visible().length?'clear':'create',can('create')?'primary':''))}</section>`}
function chart(color=0,big=false){let colors=['#7c8eab','#91a69e','#a397b4','#baa990'];let y=[64,61,65,45,49,39,44,29,32,22,26,17,21,14,16,10];if(color===1)y=y.map(v=>79-v*.8);const line=y.map((v,i)=>`${i*20},${v}`).join(' ');return `<svg viewBox="0 0 300 85" preserveAspectRatio="none" aria-label="演示训练趋势" role="img"><polyline points="${line}" fill="none" stroke="${colors[color%4]}" stroke-width="${big?1.2:1.7}" vector-effect="non-scaling-stroke"/><polyline points="${y.map((v,i)=>`${i*20},${v+(i%3)*4+7}`).join(' ')}" fill="none" stroke="${colors[color%4]}" stroke-opacity=".3" stroke-width="1.2"/></svg>`}
function card(p,org=o()){return `<article class="card project-card"><div class="project-card-header">${projectName(p,org)}${btn(icon('pin'),'pinProject','card-pin'+(isPinned(p)?' active':''),`data-id="${p.id}" data-org="${org.id}" aria-pressed="${isPinned(p)}" aria-label="${isPinned(p)?'取消置顶':'置顶'}${esc(p.name)}" title="${isPinned(p)?'取消置顶':'置顶'}"`)}<details class="project-card-menu"><summary aria-label="${esc(p.name)}的更多操作" title="更多操作">${icon('more')}</summary><div class="project-card-actions">${can('manage',p)?btn('管理项目','edit','ghost',`data-id="${p.id}"`):''}${btn(isPinned(p)?'取消置顶':'置顶','pinProject','ghost',`data-id="${p.id}" aria-pressed="${isPinned(p)}"`)}${M.isManager(s,org)?btn('移动项目','moveProject','ghost',`data-id="${p.id}" data-org="${org.id}"`):''}${btn(icon('tag')+' 编辑标签','projectTags','ghost',`data-id="${p.id}" data-org="${org.id}" ${M.canPerformAction(s,'manage',p,org)?'':'disabled'}`)}</div></details></div><p class="projectdesc" tabindex="0" data-truncated-text>${esc(p.desc||'')}</p><div class="tags card-tag-space">${p.tags.map(t=>tagMarkup(t,org)).join('')}<span class="tag-overflow" hidden aria-label="更多标签">…</span></div><div class="card-bottom"><span class="card-scope">${scopeBadge(p)}</span><span aria-label="实验数量 ${p.experiments}" title="实验数量">${icon('flask')}<strong>${p.experiments}</strong></span>${cardUpdate(p,org)}</div></article>`}

function updateTime(value,now=new Date()){const date=new Date(value),today=new Date(now);if(!Number.isFinite(+date)||!Number.isFinite(+today))return '';const day=d=>Date.UTC(d.getFullYear(),d.getMonth(),d.getDate());const days=Math.max(0,Math.floor((day(today)-day(date))/864e5));const pad=n=>String(n).padStart(2,'0');return days<=30?days+'天前':(date.getFullYear()!==today.getFullYear()?date.getFullYear()+'-':'')+pad(date.getMonth()+1)+'-'+pad(date.getDate());}
function experimentTime(p){return p.lastExperimentAt?`<time datetime="${esc(p.lastExperimentAt)}">${updateTime(p.lastExperimentAt)}</time>`:'<span aria-label="暂无更新">--</span>';}
function projectName(p,org=o()){return `<span class="project-name-wrap">${btn(esc(p.name),'open','projecttitle',`data-id="${p.id}" data-org="${org.id}" aria-label="打开项目：${esc(p.name)}" title="${esc(p.name)}"`)}<span class="project-fullname" role="tooltip">${esc(p.name)}</span></span>`;}
function projectTable(ps){return `<div class="tablewrap project-discovery"><table><colgroup><col class="project-main-col"><col class="project-tags-col"><col class="project-scope-col"><col class="project-count-col"><col class="project-time-col"><col class="project-action-col"></colgroup><thead><tr><th scope="col">项目</th><th scope="col">标签</th><th scope="col">访问范围</th><th scope="col">实验数量</th><th scope="col">最近实验更新</th><th scope="col">操作</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${projectName(p)}${p.desc?`<p class="project-purpose">${esc(p.desc)}</p>`:''}</td><td><div class="tags">${p.tags.map(t=>tagMarkup(t)).join('')}${can('manage',p)?btn(icon('edit'),'projectTags','small ghost tag-edit',`data-id="${p.id}" data-org="${o().id}" aria-label="编辑${esc(p.name)}的标签"`):''}</div></td><td>${scopeBadge(p)}</td><td><span class="experiment-count" aria-label="${p.experiments} 次实验" title="实验数量">${p.experiments}</span></td><td>${cardUpdate(p,o())||experimentTime(p)}</td><td><details class="project-card-menu admin-project-menu"><summary aria-label="${esc(p.name)}的更多操作">${icon('more')}</summary><div class="project-card-actions">${can('manage',p)?btn('管理项目','edit','ghost',`data-id="${p.id}"`):''}${btn(isPinned(p)?'取消置顶':'置顶','pinProject','ghost',`data-id="${p.id}"`)}${M.isManager(s)?btn('移动项目','moveProject','ghost',`data-id="${p.id}"`):''}</div></details></td></tr>`).join('')}</tbody></table></div>`;}
function projectPage(){const p=o().projects.find(p=>p.id===s.projectId);if(!p||!M.canAccessProject(s,p))return empty('没有项目访问权限','链接不会授予访问权。请联系组织管理员，或返回可访问的项目。',btn('返回项目','nav','primary','data-page="projects"'));
 return head(esc(p.name),'',can('manage',p)?btn(icon('settings')+' 项目设置','edit','',`data-id="${p.id}"`):'')+`<div class="row between"><h2>实验 <span class="muted">${p.experiments}</span></h2>${can('write',p)?btn(icon('plus')+' 记录实验','write','primary',`data-id="${p.id}"`):''}</div><div class="tablewrap"><table><thead><tr><th>实验名称</th><th>评估指标</th><th>更新时间</th></tr></thead><tbody><tr><td>${esc(p.name)} / latest</td><td>${esc(p.metric)}</td><td>${updateTime(p.updated)}</td></tr></tbody></table></div>`}
function memberSlotsSummary(org){const active=org.members.filter(m=>m.status==='active'),pending=org.invites.filter(i=>i.status==='pending');return `<div class="panel row between"><div><h3>${M.countMemberSlots(org)} / ${org.paid?'不限':10} 个名额</h3><p style="margin-top:5px">${active.length} 位已加入 + ${pending.length} 位待邀请 · Owner、只读成员与待邀请均占名额</p></div>${org.paid?badge('成员不限 · 按容量付费','green'):btn('升级组织','nav','','data-page="usage"')}</div>`;}
function membersPage(){if(!can('members'))return denied('成员管理');const org=o(),pending=org.invites.filter(i=>i.status==='pending'),active=org.members.filter(m=>m.status==='active'),disabled=org.members.filter(m=>m.status==='disabled');if(ui.tab==='legacy')return legacyMembersPage();let list=ui.tab==='pending'?org.invites.filter(i=>i.status==='pending'||i.status==='expired'||i.status==='revoked'):org.members.filter(m=>m.status===ui.tab);return head('成员管理'+btn(icon('info'),'rolePermissionsHelp','ghost title-help','aria-label="查看角色与权限" title="角色与权限" aria-haspopup="dialog"'),'在组织内管理协作成员。成员可访问所有「组织成员可见」项目。',btn(icon('userPlus')+' 邀请成员','invite','primary'))+`${memberSlotsSummary(org)}<div class="tabs">${[['active','已加入',active.length],['pending','待邀请',pending.length],['disabled','已禁用',disabled.length],['legacy','旧有协作者',(org.legacyCollaborators||[]).filter(c=>c.status!=='added').length]].map(([v,t,n])=>btn(`${t} <span class="muted">${n}</span>`,'membertab',v===ui.tab?'active':'',`data-value="${v}"`)).join('')}</div>${list.length?`<div class="tablewrap member-directory"><table><thead><tr><th>成员 / 邮箱</th><th>组织角色</th><th>状态</th>${ui.tab!=='pending'?'<th>项目</th><th>权限组</th><th>加入时间</th><th>最近活动</th>':''}<th>操作</th></tr></thead><tbody>${list.map(m=>`<tr ${ui.tab!=='pending'?`data-member-detail="${esc(m.id)}" tabindex="0" aria-label="查看${esc(m.name)}的成员详情"`:""}><td><div class="row"><span class="avatar">${esc((m.name||m.email).slice(0,1))}</span><div>${esc(m.name||m.email)}${m.id===s.user?' <small>你</small>':''}<small style="display:block">${esc(m.email)}</small></div></div></td><td>${ui.tab==='pending'?esc(m.role):btn(esc(m.role==='管理员'?'管理者':m.role)+icon('chevron'),'roleDetails','role-label',`data-id="${m.id}" aria-label="查看${esc(m.name)}的角色详情"`)}</td><td>${badge({active:'已加入',pending:'等待接受',disabled:'已禁用',expired:'已过期',revoked:'已撤回'}[m.status],m.status==='active'?'green':m.status==='disabled'?'red':'')}</td>${ui.tab!=='pending'?memberDirectoryCells(m,org):''}<td>${ui.tab==='pending'?(m.status==='pending'?btn('预览邀请','previewInvite','small ghost',`data-id="${m.id}"`)+btn('撤回','revoke','small ghost',`data-id="${m.id}"`):btn('重新邀请','reinvite','small',`data-id="${m.id}"`)):(m.role==='Owner'?'—':btn(icon('more'),'memberMenu','small ghost member-more',`data-id="${m.id}" aria-label="${esc(m.name)}的更多操作" aria-haspopup="menu"`))}</td></tr>`).join('')}</tbody></table></div>`:empty('此分组暂无成员','邀请、接受或恢复成员后，会显示在对应分组。')}`}
function denied(title){return empty('你没有'+title+'权限','当前组织成员身份无法执行此操作。可切换组织或联系 Owner。',btn('返回项目','nav','primary','data-page="projects"'))}
