function inviteForm(){if(!can('members'))return toast('没有成员管理权限');modal('邀请加入组织',inviteTabs('email')+`<form id="invite-form"><label class="field">受邀邮箱<input name="email" type="email" required placeholder="name@example.com"></label><label class="field">组织角色<select name="role">${options(M.isOwner(s)?['贡献者','查看者','管理员']:['贡献者','查看者'],'贡献者')}</select></label><div class="note">加入后可访问所有「组织成员可见」项目；指定成员项目仍需授权。管理员具有组织治理权，但项目授权管理仍需相应项目角色。<br>当前 ${M.countMemberSlots(o())} / ${o().paid?'不限':10} 名额。待邀请立即占位，有效期 7 天。</div><small>模拟邀请，不发送真实邮件。</small></form>`,btn('取消','close')+`<button class="primary" form="invite-form">创建邀请</button>`,()=>{$('#invite-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target);const inv=M.inviteMember(s,f.get('email'),f.get('role'));save();close();render();toast('邀请已创建 / 已存在，仅占一个名额。');previewInvite(inv.id)}catch(err){formError(err)}}})}
function previewInvite(id){const inv=o().invites.find(i=>i.id===id);if(!inv)return;modal('你收到一个空间邀请',`<div class="row" style="margin-bottom:18px"><span class="projectglyph">${icon('users')}</span><div><h3>${esc(o().name)}</h3><p>${o().region==='region-a'?'演示区域 A':'演示区域 B'}</p></div></div><div class="note">受邀邮箱：${esc(inv.email)}<br>组织角色：${inv.role}<br>加入后可访问组织成员可见项目，不自动获得所有指定成员项目授权。<br>待邀请转为已加入，名额不会增加。</div><form id="accept-form"><label class="field">当前登录邮箱（可修改以验证身份不匹配）<input type="email" name="email" value="${esc(inv.email)}" required></label><label class="field">账号国家<select name="country">${options(['中国','日本','美国','新加坡'],s.country)}</select>${infoTip('国家不限制接受邀请，组织数据区保持不变。')}</label></form><p>邀请状态：${{pending:'待接受',accepted:'已接受',revoked:'已撤回',expired:'已过期'}[inv.status]} · 到期 ${inv.expires.slice(0,10)}</p>`,btn('暂不接受','close')+`<button class="primary" form="accept-form">${inv.status==='accepted'?'进入组织':'接受并进入组织'}</button>`,()=>{$('#accept-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target);M.acceptInvite(s,id,f.get('email'));s.country=s.country||'中国';s.page='orgOverview';save();close();render();toast('已加入目标空间，原待邀请名额转为成员名额。')}catch(err){formError(err)}}})}
