function orderModal(id){const order=o().orders.find(x=>x.id===id);modal('模拟支付 · 订单确认',`<p>组织：<strong>${esc(o().name)}</strong></p><div class="stats" style="grid-template-columns:1fr 1fr"><div class="stat"><small>目标总容量</small><div class="value">${order.gb} GB</div></div><div class="stat"><small>演示价格</small><div class="value">¥${order.price}<small>/月</small></div></div><p>确认后，总容量替换为 ${order.gb} GB，成员人数不限；原有数据和权限保留。</p><div class="note">模拟支付，不产生真实扣款。订单 ${order.id}<br>当前状态：${order.status}。只有成功结果会更新权益；重复成功不重复扩容。</div><div class="row wrap">${[['success','确认模拟支付'],['failed','模拟失败'],['cancelled','取消支付'],['processing','保持处理中']].map(([v,t])=>btn(t,'pay',v==='success'?'primary':'',`data-id="${id}" data-value="${v}"`)).join('')}</div>`)}
