function renderPublic(){const p=o().projects.find(p=>p.id===s.projectId);if(!p||p.scope!=='PUBLIC_READONLY'){ui.public=false;render();return}const pub=M.publicProject(p);renderPage(`<div class="publicheader"><div class="brand" title="SwanLab"><button class="sidebar-toggle" data-action="sidebarToggle" aria-label="${ui.sidebarCollapsed?'展开侧边栏':'收起侧边栏'}" title="${ui.sidebarCollapsed?'展开侧边栏':'收起侧边栏'}">${icon('chevron')}</button><a class="brand-home" href="https://swanlab.cn/home" target="_blank" rel="noopener noreferrer" aria-label="SwanLab 官网（新标签页打开）" title="SwanLab 官网"><img src="logo.png" alt="" width="28" height="28"></a>SwanLab</div><div class="row">${badge('公开只读')}${badge('演示环境')}${btn('退出访客预览','exitPublic')}</div></div><main class="publicmain" id="content">${head(esc(pub.name),'公开项目 · 只读概览与实验数值')}${badge(icon('globe')+' 互联网公开')}<p style="margin:20px 0 30px">${esc(pub.desc)}</p><div class="stats"><div class="stat"><small>公开实验摘要</small><div class="value">${pub.experiments}</div></div><div class="stat"><small>评估指标</small><div class="value">${pub.metric}</div></div><div class="stat"><small>访问方式</small><div class="value" style="font-size:22px">公开只读</div></div></div><div class="panel"><h3>实验数值趋势</h3><div class="cardchart" style="height:240px;margin:25px 0">${chart(1,true)}</div></div><div class="note">公开视图只返回允许的项目摘要和数值。原文件、媒体、导出及内部成员资料不对公开访客开放。</div></main>`);bind()}
function renderAuth(){ renderPage(`<main class="auth auth-layout" id="content"><aside class="auth-story" aria-label="SwanLab 实验协作"><a class="brand brand-home" href="https://swanlab.cn/home" target="_blank" rel="noopener noreferrer"><img src="logo.png" alt="" width="26" height="26">SwanLab</a><div class="auth-particle-field" aria-hidden="true"><canvas></canvas></div><div class="auth-story-copy"><p class="auth-story-eyebrow">TRACK. COMPARE. DISCOVER.</p><h2 class="auth-story-title" aria-label="让每一次实验，都有迹可循。"><span aria-hidden="true"><span data-ghost-prefix>让每一次实验，</span><span data-ghost-ending></span><i class="ghost-caret"></i></span></h2><p class="auth-story-detail">记录每一次探索，连接每一个发现。<br>让你和团队专注于下一个突破。</p></div><footer class="auth-story-footer"><span>为研究而生，与发现同行。</span></footer></aside><section class="auth-form-panel" aria-labelledby="auth-title"><span class="auth-mark" aria-hidden="true">${icon('sparkles')}</span><h1 id="auth-title">${ui.addAccount?'添加账户':s.loggedOut?'欢迎回来':'从一次新探索开始'}</h1><p>${ui.addAccount?'登录其他账户，之后可在账号菜单中切换。':'登录 SwanLab，继续你的项目探索。'}</p><form id="auth-form"><label class="field">姓名<input name="name" required maxlength="40" placeholder="你的姓名" autocomplete="name"></label><label class="field">邮箱<input name="email" type="email" required placeholder="name@example.com" autocomplete="email"></label><button class="primary" type="submit">注册 / 登录并进入</button><div id="auth-error" role="alert"></div></form>${!s.loggedOut?btn(ui.addAccount?'返回当前账户':'返回已有演示组织','backFromAuth','ghost','style="width:100%;margin-top:15px"'):''}</section></main>`);mountAuthMotion();mountAuthParticles();bind();$('#auth-form').onsubmit=e=>{e.preventDefault();if(new URLSearchParams(location.search).get('preview')==='login'){const url=new URL(location.href);url.searchParams.delete('preview');history.replaceState(null,'',url);} const f=new FormData(e.target),email=f.get('email').trim().toLowerCase(),name=f.get('name').trim();if(!name)return;const existing=s.orgs.flatMap(org=>org.members).find(m=>m.email===email);if(!existing){s.registration={name,email,country:s.country||'中国',step:'organizations'};s.loggedOut=false;save();render();return;}const target=existing?s.orgs.find(org=>org.members.some(m=>m.id===existing.id&&m.status==='active')):M.initializeAccount(s,email,name,f.get('country'));if(!target){$('#auth-error').textContent='本组织协作已禁用，请联系管理员';return;}s.orgId=target.id;s.user=existing?.id||target.members.find(m=>m.email===email).id;s.loggedOut=false;ui.addAccount=false;M.rememberAccount(s);s.country=s.country||'中国';s.page='orgOverview';save();render();toast('登录成功，已进入组织概览。')}}
