function action(a,d){if(groupUI.action(a,d))return;if(billingUI.action(a,d))return;if(groupUI.changed()&&s.page==='permissionGroup'&&['nav','open','switchOrg','logout','create'].includes(a)){if(!window.confirm('权限组尚未保存，放弃更改？'))return;groupUI.discard();}if(['choosePlan','pay','order'].includes(a)){toast('旧容量购买流程已停用，请使用账单页的订阅管理');return;}document.querySelectorAll('.project-card-actions[popover]:popover-open').forEach(pop=>pop.hidePopover());document.querySelectorAll('.project-card-menu[open]').forEach(menu=>menu.open=false);if(ui.orgDirty&&['nav','open','switchOrg','logout','addAccount','create'].includes(a)){if(!window.confirm('组织信息尚未保存，确定放弃更改？'))return;ui.orgDirty=false;ui.orgAvatar=undefined;ui.orgDraft=undefined;}if(extraAction(a,d))return;switch(a){case'onboardStart':s.registration.step='organization';save();render();break;case'onboardCancel':s.registration.step='organizations';save();render();break;case'addLegacy':legacyAddForm(d.id);break;case'accountMenu':toggleAccountMenu();break;case'dismissCapacityAlert':{const r=M.checkCapacity(o());ui.dismissedCapacityAlert=o().id+':'+r.status+':'+o().used+':'+o().capacity;render();break;}case'sidebarToggle':ui.sidebarCollapsed=!ui.sidebarCollapsed;localStorage.setItem('swanlab-sidebar-demo2',ui.sidebarCollapsed?'collapsed':'expanded');render();break;case'theme':setTheme(d.value);break;case'addAccount':$('#account-menu')?.hidePopover();s.page='auth';ui.addAccount=true;save();render();break;case'logout':s.registration=null;$('#account-menu')?.hidePopover();M.signOut(s);ui.addAccount=false;save();render();toast(s.loggedOut?'已退出演示账号':'已退出当前账号，切换至另一个已登录账号');break;case'activateAccount':run(()=>M.activateAccount(s,d.id));break;case'profileTab':ui.profileTab=d.value;render();break;case'switchOrg':switchOrg(d.id);break;case'nav':s.page=d.page;save();render();focusContent();break;case'open':if(d.org)s.orgId=d.org;s.projectId=d.id;s.page='project';save();render();focusContent();break;case'create':projectForm();break;case'edit':projectForm(d.id);break;case'close':close();break;case'view':ui.view=d.value;s.profiles[s.user].projectView=d.value;save();render();break;case'resetProjectFilters':ui.search='';ui.scope=ui.tag='all';ui.sort='date';render();break;case'clear':ui.search='';ui.scope=ui.tag='all';render();break;case'recentView':ui.recentView=['all','projects','experiments'].includes(d.value)?d.value:'all';render();break;case'membertab':ui.tab=d.value;render();break;case'dev':ui.dev=!ui.dev;render();break;case'retry':s.regionFailure=false;s.requestFailure=false;save();render();toast('已重新连接，状态保持');break;case'invite':inviteForm();break;case'previewInvite':previewInvite(d.id);break;case'revoke':confirmDialog('撤回邀请？','撤回后链接不再有效，释放一个待邀请名额。',()=>{if(!can('members'))throw Error('无权限');o().invites.find(i=>i.id===d.id).status='revoked';toast('邀请已撤回，名额已释放')});break;case'reinvite':run(()=>{const inv=o().invites.find(i=>i.id===d.id);M.inviteMember(s,inv.email,inv.role);toast('已重新创建邀请')});break;case'memberstatus':confirmDialog(d.value==='active'?'恢复空间协作？':'禁用本组织协作？',d.value==='active'?'恢复后沿用已有项目授权，重新获得组织成员可见项目访问权。':'仅影响本组织。历史数据、账号与其他组织访问保持；本组织项目的协作授权将失效。',()=>{M.setMemberStatus(s,d.id,d.value);toast(d.value==='active'?'成员协作已恢复':'成员仅在本组织禁用，名额已释放')});break;
 case'write':run(()=>{const p=o().projects.find(p=>p.id===d.id);M.writeExperiment(s,p);toast('演示实验已记录，组织存储增加 0.1 GB')});break;case'resource':run(()=>{const p=o().projects.find(p=>p.id===d.id);if(!can(d.type,p))throw Error('没有资源权限');modal(d.type==='media'?'演示媒体预览':'演示资源已就绪',d.type==='media'?'<div class="note">模型评估样本 #001 · 内部授权媒体</div><p>这是媒体查看权限演示，没有加载真实用户文件。</p>':'<p>当前身份已通过资源访问检查。这是下载 / 导出模拟，不包含真实实验文件。</p>')});break;case'copyLink':{const link=new URL(location.href);link.search='';link.searchParams.set('org',o().id);link.searchParams.set('project',d.id);navigator.clipboard.writeText(link.href).then(()=>toast('链接已复制。链接仅定位项目，不授予访问权限。')).catch(()=>toast('复制不可用，请使用当前项目地址：'+link.href));break;}case'public':s.projectId=d.id;ui.public=true;render();break;case'exitPublic':ui.public=false;render();break;case'buy':buy();break;case'storagePurchase':storagePurchase();break;case'usageOpenProject':if(can('usage')&&o().projects.some(p=>p.id===d.id&&M.canAccessProject(s,p))){close();s.projectId=d.id;s.page='project';save();render();}break;case'usageProject':if(can('usage')&&o().projects.some(p=>p.id===d.id&&M.canAccessProject(s,p))){usageProject(d.id);}break;case'pricing':if(can('billing'))pricingUI.open();break;case'choosePlan':run(()=>{if(!M.isOwner(s))throw Error('仅 Owner 可购买');const order={id:'DEMO-'+Date.now(),gb:+d.gb,price:+d.price,status:'pending',applied:false};o().orders.push(order);save();orderModal(order.id)});break;case'order':orderModal(d.id);break;case'pay':try{M.applyPaymentResult(s,d.id,d.value);save();close();s.page='usage';render();toast({success:'模拟支付成功，目标总容量已生效，成员人数不限。',failed:'模拟支付失败，容量与组织权益保持。',cancelled:'支付已取消，未改变权益。',processing:'订单处理中，权益尚未生效。'}[d.value])}catch(e){formError(e)}break;
 case'cleanup':confirmDialog('清理演示数据','本操作模拟从各项目按比例释放 1 GB 存储。实验记录数量保持，生产删除与回收站规则待确认。',()=>{if(!can('usage'))throw Error('无权清理');M.setUsage(o(),Math.max(0,o().used/1e9-1));toast('已释放演示容量 1 GB')});break;case'trial':switchOrg('trial');s.page='members';ui.tab='legacy';save();render();break;case'expireTrial':run(()=>{if(!can('migration'))throw Error('无权操作');s.now=o().trial.end;M.finalizeMigrationTrial(s);toast('到期处理已执行。历史数据与其他组织不受影响。')});break;case'disabledMembers':s.page='members';ui.tab='disabled';save();render();break;
 case'transfer':transfer();break;case'acceptTransfer':acceptTransfer();break;case'transferResult':try{const t=o().transfer;if(!t)throw Error('转移请求不存在');if(d.value==='failed')throw Error('模拟处理失败，原 Owner 保持，未产生第二个 Owner');if(d.value==='accept'){const target=o().members.find(m=>m.id===t.to&&m.status==='active');if(!target)throw Error('接收者不再是有效成员');o().members.find(m=>m.id===t.from).role='管理员';target.role='Owner';o().owner=target.id;s.user=target.id}delete o().transfer;save();close();render();toast(d.value==='accept'?'Owner 原子交接完成，项目仍归组织所有。已切换至接收者。':'对方已拒绝，原 Owner 保持。')}catch(e){formError(e)}break;
 case'manageTags':manageTags();break;case'tagForm':tagForm(d.name);break;case'deleteTag':confirmDialog('删除标签？','只解除标签引用，不删除项目，不改变项目权限与存储。',()=>{M.deleteTag(s,d.name);if(ui.tag===d.name)ui.tag='all';toast('标签已删除，项目保留')});break;case'projectTags':projectTags(d.id,d.org);break;case'command':commandPalette();break;case'profileEdit':profileEdit();break;
 case'auth':s.page='auth';save();render();break;case'backFromAuth':{const url=new URL(location.href);url.searchParams.delete('preview');history.replaceState(null,'',url);}s.page='projects';save();render();break;case'reset':confirmDialog('重置全部演示数据？','将恢复初始账号、三组组织、容量、订单与迁移时间。',()=>{s=M.seed();ui={...ui,search:'',scope:'all',tag:'all',tab:'active'};toast('全部演示数据已重置')});break;
 case'help':modal('Project V0.4.2 · 功能原型','<p>验证组织 → 项目 → 实验的结构，以及权限、名额、容量与迁移流程。</p><div class="note">所有账号、区域、价格、支付与数据均为模拟。数据保存在当前浏览器，可在验证面板重置。<br>打开验证面板，切换贡献者或查看者可检查隐藏项目与动作权限；切换区域故障和模拟时钟可检查异常流程。</div><p>本原型采用 PRD A01–A14 假设；不代表生产鉴权、支付或多区基础设施已实现。</p>');break;case'enterprise':modal('Enterprise 定制说明','<p>Enterprise 将按定制功能收费，具体功能与容量费组合待确认。</p><div class="note">此处为咨询占位，没有发送消息，也未创建销售线索。</div>');break;}}
