function roleDetails(id){const m=o().members.find(m=>m.id===id);if(!m)return;const descriptions={Owner:'拥有组织的全部治理权限，可管理成员和项目、购买容量、管理账单及转移 Owner。可访问并管理本组织全部项目。',管理员:'可管理组织成员与项目治理；项目授权管理仍需相应项目角色。不能转移 Owner 或执行仅 Owner 可操作的账单与组织操作。',贡献者:'可读取组织成员可见项目，并在其内记录实验；指定成员项目按单独授权访问。没有组织治理权限。',查看者:'可读取组织成员可见项目；不能新增实验。指定成员项目仍需授权。没有组织治理权限。'};modal('Role details',`<section class="role-detail-section"><h3>Account</h3><div class="row" style="margin-top:16px"><span class="avatar">${esc(m.name.slice(0,1))}</span><div><strong>${esc(m.name)}</strong><small style="display:block">ID: ${esc(m.id)}</small><small>${esc(m.email)}</small></div></div></section><section class="role-detail-section"><h3>Role</h3><p style="margin-top:12px">${esc(m.role==='管理员'?'管理者':m.role)}</p>${m.status==='active'&&m.role!=='Owner'&&(M.isOwner(s)||m.role!=='管理员')?`<label class="field" style="margin-top:16px">调整角色<select data-member-role="${m.id}">${options(roles.slice(1).filter(r=>M.isOwner(s)||r!=='管理员'),m.role)}</select></label>`:''}</section><section class="role-detail-section"><h3>Description</h3><p style="margin-top:12px">${esc(descriptions[m.role])}</p><div class="note">${m.status==='disabled'?'当前账户已在本组织禁用，以上角色权限暂不生效。':'个人及权限组可提供项目授权；组织角色保持独立，治理身份不自动提供项目授权管理权。'}</div></section>`,btn('关闭','close'));$('#modal').classList.add('role-drawer');$('#modal [data-member-role]')?.addEventListener('change',()=>{if($('#modal').open)close();roleDetails(id)});}
