function memberMenu(id){const m=o().members.find(m=>m.id===id);if(!m)return;document.querySelector('#member-actions')?.remove();const trigger=[...($('#modal').open?$('#modal'):document).querySelectorAll('[data-action="memberMenu"]')].find(el=>el.dataset.id===id),menu=document.createElement('div');menu.id='member-actions';menu.setAttribute('popover','auto');menu.setAttribute('role','menu');const allowed=can('members')&&m.role!=='Owner'&&(M.isOwner(s)||m.role!=='管理员');menu.innerHTML=btn('转移资源','transferMemberResources','',`data-id="${id}" role="menuitem" ${allowed?'':'disabled'}`)+btn(m.status==='disabled'?'恢复账号':'停用账号','confirmMemberStatus',m.status==='disabled'?'':'danger',`data-id="${id}" data-value="${m.status==='disabled'?'active':'disabled'}" role="menuitem" ${allowed?'':'disabled'}`);menu.innerHTML+=btn('移除成员','removeMember','danger',`data-id="${id}" role="menuitem" ${allowed?'':'disabled'}`);($('#modal').open?$('#modal'):document.body).append(menu);bind(menu);const r=trigger.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(r.right-160,innerWidth-168))+'px';menu.style.top=Math.min(r.bottom+5,innerHeight-70)+'px';menu.showPopover();menu.querySelector('button').focus();menu.addEventListener('toggle',e=>{if(e.newState==='closed')trigger?.focus()});}
function confirmMemberStatus(id,status){const m=o().members.find(m=>m.id===id);if(!m)return;const disabling=status==='disabled';modal(disabling?'禁用账户？':'恢复账户？',`<div class="${disabling?'error':'note'}"><strong>${disabling?'此操作将立即停止该成员在本组织的数据访问和协作。':'恢复后成员将重新获得本组织协作权限。'}</strong></div><p style="margin-top:16px">${esc(m.name)} · ${esc(m.email)}</p><p style="margin-top:12px">${disabling?'仅在当前组织禁用，释放成员名额；历史数据和其他组织的访问不受影响。可从「已禁用」恢复账户。':'沿用原组织角色和项目授权，恢复后占用一个成员名额。'}</p>`,btn('取消','close')+btn(disabling?'确认禁用账户':'确认恢复账户','applyMemberStatus',disabling?'danger':'primary',`data-id="${id}" data-value="${status}"`),()=>{$('#modal [data-action="applyMemberStatus"]').onclick=()=>{try{M.setMemberStatus(s,id,status);save();close();render();toast(disabling?'账户已在当前组织禁用':'账户协作已恢复')}catch(err){formError(err)}}});}

