function rolePermissionsPage(drawer=false){if(!M.isManager(s))return denied('角色与权限');return (drawer?'':head('角色与权限','查看组织角色与资源级权限。'))+section('内置角色',`<div class="tablewrap"><table><thead><tr><th>角色</th><th>权限说明</th></tr></thead><tbody>${[['Owner','组织全部治理权限；管理成员与项目、购买容量、管理账单、转移 Owner。'],['管理者','管理组织成员与项目治理；维护权限组还需检查相应项目授权管理权，不能执行仅 Owner 可用的操作。'],['贡献者','可读取组织成员可见项目并记录实验；指定成员项目需要个人或权限组授权。'],['查看者','可读取组织成员可见项目；不能记录实验。指定成员项目需要个人或权限组授权。'],['账单联系人（非成员角色）','用于接收账单通知，本身不授予数据或操作权限；可兼任任何组织角色，权限独立判定。仅联系人不占名额，兼具成员或待接受邮箱邀请身份不重复计数。']].map(([role,desc])=>`<tr><td><strong>${role}</strong></td><td style="white-space:normal">${desc}</td></tr>`).join('')}</tbody></table></div>`)+section('自定义角色',`<p>本期使用现有项目角色：管理、贡献、查看。权限组按项目配置角色；自定义角色与动作勾选后置。</p>`)+section('权限组',`<p>一组组织成员可以在不同项目拥有不同角色；加入组不改变组织角色。个人直接授权与多个组按允许动作合并，撤销一个来源后其他来源仍有效。管理组成员需拥有全部关联项目的授权管理权。</p>`)+section('资源级权限',`<div class="tablewrap"><table><thead><tr><th>资源范围</th><th>访问与授权规则</th></tr></thead><tbody><tr><td>指定成员项目</td><td>由项目名单授予管理、贡献或查看权限；组织治理身份不自动提供项目授权管理权，个人及权限组可分别授权。</td></tr><tr><td>组织成员可见项目</td><td>有效组织成员可读取；贡献者可写入，查看者不可写入。</td></tr><tr><td>公开只读项目</td><td>访客仅可读取公开摘要与数值；不授予内部名单、媒体、原文件或导出权限。</td></tr><tr><td>禁用账户</td><td>本组织协作权限失效；历史记录与其他组织权限保持。</td></tr><tr><td>账单联系人</td><td>联系人身份不授予数据、购买、套餐变更或成员管理权限；可通过独立的组织角色和项目授权获得相应权限。仅 Owner 可管理联系人。</td></tr></tbody></table></div>${infoTip('组织角色、直接授权与权限组共同决定实际权限。资源权限的具体调整在项目管理的「成员与权限」中完成。')}`)}

