function infoTip(text){const id='help-'+(++helpSequence);return `<span class="inline-help"><button type="button" class="info-tip-trigger" aria-label="查看补充说明" aria-describedby="${id}">${icon('info')}</button><span id="${id}" class="info-tip-content" role="tooltip">${esc(text)}</span></span>`;}
function accessibleHelp(root){root.querySelectorAll('label.field').forEach(label=>{const controls=label.querySelectorAll('input:not([type=hidden]),select,textarea');if(controls.length!==1)return;const control=controls[0];if(!control.id)control.id='field-'+(++helpSequence);label.htmlFor=control.id;const helpers=[...label.querySelectorAll('.inline-help')];if(!helpers.length)return;const textNodes=[...label.childNodes].filter(n=>n.nodeType===3),caption=textNodes.map(n=>n.textContent.trim()).join(' '),field=document.createElement('div');field.className=label.className;field.classList.add('field-help-row');const captionRow=document.createElement('span');captionRow.className='field-help-caption';const title=document.createElement('label');title.htmlFor=control.id;title.textContent=caption;captionRow.append(title);label.before(field);textNodes.forEach(n=>n.remove());field.append(captionRow);helpers.forEach(help=>{const tip=help.querySelector('[role=tooltip]');if(tip){const ids=new Set((control.getAttribute('aria-describedby')||'').split(' ').filter(Boolean));ids.add(tip.id);control.setAttribute('aria-describedby',[...ids].join(' '));}help.querySelector('button')?.setAttribute('aria-label',(caption||'字段')+'说明');captionRow.append(help);});field.append(...label.childNodes);label.remove();});root.querySelectorAll('.inline-help').forEach(help=>{if(!help.closest('.field-help-caption')){const section=help.closest('.setting-section'),panel=help.closest('.panel'),details=help.closest('details');let title=details?.querySelector('summary')||section?.querySelector('h2')||panel?.querySelector('h3');if(!title){const headings=[...root.querySelectorAll('h1,h2,h3,summary')];title=headings.filter(h=>!!(h.compareDocumentPosition(help)&Node.DOCUMENT_POSITION_FOLLOWING)).at(-1);}if(title){const caption=title.textContent.trim();title.append(help);help.querySelector('button')?.setAttribute('aria-label',caption+'说明');}}help.addEventListener('keydown',event=>{if(event.key==='Escape'){help.classList.add('help-dismissed');event.stopPropagation();}});help.addEventListener('pointerleave',()=>help.classList.remove('help-dismissed'));help.addEventListener('focusout',()=>help.classList.remove('help-dismissed'));});}

function cardUpdate(p,org){if(!p.lastExperimentAt||!p.lastExperimentBy)return '';const person=org.members.find(m=>m.id===p.lastExperimentBy),profile=s.profiles[p.lastExperimentBy],name=profile?.name||person?.name||'更新者';const relative=updateTime(p.lastExperimentAt);if(!relative)return '';return `<span class="card-update" aria-label="${esc(name)}，${relative}" title="${esc(name)} · ${esc(p.lastExperimentAt)}">${profile?.avatar?`<img class="update-avatar" src="${esc(profile.avatar)}" alt="${esc(name)}">`:`<span class="update-avatar" aria-hidden="true">${esc(name.slice(-2))}</span>`}<time datetime="${esc(p.lastExperimentAt)}">${relative}</time></span>`;}

function legacyMembersPage(){const org=o(),all=org.legacyCollaborators||[],waiting=all.filter(c=>c.status!=='added');return head('成员管理'+btn(icon('info'),'rolePermissionsHelp','ghost title-help','aria-label="查看角色与权限"'),' ',btn(icon('userPlus')+' 邀请成员','invite','primary'))+memberSlotsSummary(org)+`<div class="tabs">${[['active','已加入',org.members.filter(m=>m.status==='active').length],['pending','待邀请',org.invites.filter(i=>i.status==='pending').length],['disabled','已禁用',org.members.filter(m=>m.status==='disabled').length],['legacy','旧有协作者',waiting.length]].map(([v,t,n])=>btn(`${t} <span class="muted">${n}</span>`,'membertab',v===ui.tab?'active':'',`data-value="${v}"`)).join('')}</div><p class="note">旧有协作者已移出项目。加入组织时可选择恢复原项目权限；组织角色权限独立生效。</p>${all.length?`<div class="tablewrap"><table><thead><tr><th>协作者 / 邮箱</th><th>原项目与权限</th><th>状态</th><th>操作</th></tr></thead><tbody>${all.map(c=>`<tr><td><div class="row"><span class="avatar">${esc(c.name.slice(0,1))}</span><div>${esc(c.name)}<small style="display:block">${esc(c.email)}</small></div></div></td><td>${c.grants.map(g=>{const p=org.projects.find(p=>p.id===g.projectId);return p?`<div>${esc(p.name)} · ${esc(g.role)}</div>`:''}).join('')||'—'}</td><td>${badge(c.status==='added'?'已加入组织':'已移出项目',c.status==='added'?'green':'')}</td><td>${c.status==='added'?'—':btn('加入组织','addLegacy','small',`data-id="${esc(c.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无旧有协作者','')}`;}
function legacyAddForm(id){const c=o().legacyCollaborators.find(c=>c.id===id);if(!c)return;modal('加入组织',`<form id="legacy-add-form"><p>${esc(c.name)} · ${esc(c.email)}</p><label class="field">组织角色<select name="role">${options(['贡献者','查看者'],'贡献者')}</select></label><label class="checkrow"><input type="checkbox" name="restorePermissions" checked><span>恢复原项目权限</span></label><p class="note">将占用一个组织成员名额；已有成员或待邀请按邮箱去重。取消勾选后不恢复原项目授权，所选组织角色对应的权限仍会生效。</p></form>`,btn('取消','close')+'<button class="primary" form="legacy-add-form">加入组织</button>',()=>{$('#legacy-add-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),restore=f.has('restorePermissions');M.addLegacyCollaborator(s,id,f.get('role'),restore);save();close();render();toast(restore?'已加入组织，原项目权限已恢复':'已加入组织，未恢复原项目授权')}catch(err){formError(err)}}});}

function renderOnboarding(){const r=s.registration;applyTheme();renderPage(`<div class="onboarding-shell"><header class="onboarding-header"><a href="https://swanlab.cn/home" target="_blank" rel="noopener noreferrer" aria-label="SwanLab 官网"><img src="logo.png" width="24" height="24" alt=""></a><span>/</span><span>${r.step==='organization'?'新建组织':r.step==='project'?'<span class="org-symbol">'+esc(o().name.slice(0,1))+'</span> '+esc(o().name)+' <small class="org-plan-badge">'+(o().paid?'TEAM':'FREE')+'</small></span><span>/</span><span>创建项目':'我的组织'}</span>${onboardingAccountTrigger(r.name)}</header><main id="content" class="onboarding-main">${r.step==='organizations'?`<h1>我的组织</h1><section class="onboarding-empty">${icon('plus')}<h2>创建组织</h2><p class="onboarding-subtitle">在组织中管理项目、协作成员与共享资源。</p>${btn(icon('plus')+' 创建组织','onboardStart','primary')}</section>`:r.step==='organization'?`<section class="onboarding-card"><header><h1>创建新组织</h1></header><form id="onboard-org">${organizationCreateFields(r.name+'的组织')}<div id="onboard-error" role="alert"></div><footer>${btn('取消','onboardCancel')}<button class="primary">创建组织</button></footer></form></section>`:'<section class="onboarding-card" id="onboard-project"></section>'}</main></div>${accountMenuMarkup()}`);bind();if(r.step==='organization')$('#onboard-org').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),name=f.get('name').trim();if(!name)throw Error('请输入组织名称');const org=M.initializeAccount(s,r.email,r.name,r.country);org.name=name;org.region='region-a';applyInitialPlan(org,f.get('plan'));s.orgId=org.id;s.user=org.owner;s.country=r.country;M.upgradePrototypeState(s);
// Normalize persisted demo data to the English project copy.
const projectCopy={
 'Qwen3 · 指令微调':['Qwen3 · Instruction Tuning','Explore lightweight training with traceable experiments.'],
 '多模态检索 · 评估集':['Multimodal Retrieval · Evaluation Set','Unified text and image representations for cross-modal retrieval.'],
 'Research / 未发布模型':['Research / Unreleased Model','An internal research project protected for specific members.'],
 'ImageNet / ResNet-50':['ImageNet / ResNet-50','Image classification baseline comparing learning rates and augmentation strategies.']
};
for(const org of s.orgs||[])for(const project of org.projects||[]){const copy=projectCopy[project.name];if(copy){project.name=copy[0];project.desc=copy[1];}}
s.profiles[s.user]??={name:r.name};M.rememberAccount(s);r.step='project';save();render();}catch(err){$('#onboard-error').textContent=err.message}};if(r.step==='project')mountProjectCreateForm();}


function organizationCreateFields(name=''){return `<label class="field org-create-field">组织名称<span class="control-hint"><input name="name" aria-label="组织名称" required maxlength="80" value="${esc(name)}" placeholder="例如：视觉智能实验室" aria-describedby="org-name-hint"><small id="org-name-hint">用于识别你的团队或工作空间，可随时修改。</small></span></label><label class="field org-create-field">套餐<span class="control-hint"><select name="plan" aria-label="套餐" aria-describedby="org-plan-hint">${opt('free','免费 · 10 GB','free')}${opt('pro','付费 · 100 GB','free')}</select><small id="org-plan-hint">免费套餐包含 10 个成员名额；付费套餐成员人数不限。仅本地模拟，不产生费用。</small></span></label>`;}
function applyInitialPlan(org,plan){org.paid=plan==='pro';org.capacity=org.paid?1e11:1e10;}
function scopePicker(selected){const descriptions={MEMBERS:'指定个人、权限组成员及本组织治理者可访问。',SPACE:'组织内所有有效成员可读取，贡献者可记录实验。',PUBLIC_READONLY:'所有人可读取公开概览与数值，不含内部名单、原文件、媒体和导出。'};return `<div class="field scope-field"><span id="scope-label">可见范围</span><input type="hidden" name="scope" id="form-scope" value="${selected}"><details id="scope-picker" class="scope-picker"><summary aria-labelledby="scope-label scope-selected"><span id="scope-selected">${scopes[selected]}</span>${icon('chevron')}</summary><div class="scope-options" role="group" aria-label="可见范围">${Object.entries(scopes).map(([value,label])=>`<button type="button" data-scope-choice="${value}" aria-label="${label}：${descriptions[value]}" aria-pressed="${selected===value}"><strong>${label}</strong><small>${descriptions[value]}</small></button>`).join('')}</div></details></div>`;}

function renderProjectCreatePage(){applyTheme();const name=s.profiles[s.user]?.name||M.member(s)?.name||'';renderPage(`<div class="onboarding-shell"><header class="onboarding-header"><a href="https://swanlab.cn/home" target="_blank" rel="noopener noreferrer" aria-label="SwanLab 官网"><img src="logo.png" width="24" height="24" alt=""></a><span>/</span><span class="create-org-crumb"><span class="org-avatar-small">${o().avatar?`<img src="${esc(o().avatar)}" alt="">`:esc(o().name.slice(0,1))}</span>${esc(o().name)}<span class="badge org-plan">${o().paid?'TEAM':'FREE'}</span></span><span>/</span><span>创建项目</span>${onboardingAccountTrigger(name)}</header><main id="content" class="onboarding-main"><section class="onboarding-card" id="onboard-project"></section></main></div>${accountMenuMarkup()}`);bind();mountProjectCreateForm();}
function mountProjectCreateForm(){projectForm(undefined,true);const dialog=$('#modal'),card=$('#onboard-project');for(const child of [...dialog.children])card.append(child);dialog.close();const header=card.querySelector('.modalhead');header.querySelector('button')?.remove();header.insertAdjacentHTML('beforeend',`<p class="project-create-subtitle">一个项目能容纳多个训练实验，记录实验的超参数、指标、日志和环境信息，并通过表格和看板比较实验差异。</p><a class="project-example-link" href="https://docs.swanlab.cn/examples/mnist.html" target="_blank" rel="noopener noreferrer">${icon('book')}看看案例<span class="example-chevron" aria-hidden="true"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path class="example-chevron-top" d="M6 4L10 8"/><path class="example-chevron-bottom" d="M10 8L6 12"/></svg></span></a>`);const cancel=card.querySelector('[data-action="close"]');const form=card.querySelector('form'),initial=JSON.stringify([...new FormData(form)]);const leave=()=>{s.registration=null;s.page='orgOverview';save();render();focusContent();};const requestLeave=()=>{if(JSON.stringify([...new FormData(form)])===initial){leave();return;}modal('放弃未保存的项目？','<p>填写的项目信息尚未保存，离开后将丢失。</p>',btn('继续编辑','close')+'<button type="button" id="confirm-leave-project" class="danger">放弃并离开</button>',()=>{$('#confirm-leave-project').onclick=()=>{close();leave();}});};cancel.onclick=requestLeave;const crumb=document.querySelector('.create-org-crumb')||document.querySelector('.onboarding-header>span:nth-of-type(2)');if(crumb){crumb.setAttribute('role','button');crumb.setAttribute('tabindex','0');crumb.setAttribute('aria-label','返回'+o().name+'组织概览');crumb.onclick=requestLeave;crumb.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();requestLeave();}};}}
function projectCreatedDialog(project){modal('项目创建成功',`<p><strong>${esc(project.name)}</strong> 已创建。</p><p class="demo-path">演示路径：创建组织 → 创建项目 → 进入项目页面。</p><p>实际产品中，下一步将进入该项目页面。项目页面不属于本次改版范围，本原型在此结束演示。</p>`,btn('返回所有项目','close','primary'));}

function matchesFilter(value,item){return !value||value==='all'||String(value).split('|').some(v=>Array.isArray(item)?item.includes(v):v===item);}
function setupListFilters(root){const configs=[['scope-filter','scope','可见范围','all',true],['tag-filter','tag','标签','all',true],['sort','sort','排序方式','date',false],['admin-scope','adminScope','可见范围','all',true],['admin-sort','adminSort','排序方式','updated',false],['trash-sort','trashSort','排序方式','recent',false]];for(const [id,key,label,base,multiple] of configs){if(!multiple)continue;const select=root.querySelector('#'+id);if(!select)continue;const choices=[...select.options].filter(x=>!multiple||x.value!=='all').map(x=>({value:x.value,label:x.textContent})),current=ui[key]||base,selected=current===base&&multiple?[]:current.split('|');const wrap=document.createElement('div');wrap.className='list-filter';select.before(wrap);wrap.append(select);select.hidden=true;const chosen=choices.filter(x=>selected.includes(x.value));const trigger=document.createElement('button');trigger.type='button';trigger.className='filter-trigger'+(current===base?' is-empty':'');trigger.id=id+'-trigger';trigger.setAttribute('aria-label',label);trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-expanded','false');trigger.innerHTML=`<span>${esc(multiple?(chosen.length?chosen.map(x=>x.label).join('、'):label):(chosen[0]?.label||label))}</span>${icon('chevron')}`;wrap.append(trigger);const pop=document.createElement('div');pop.className='filter-popover';pop.id=id+'-popover';pop.setAttribute('popover','auto');pop.setAttribute('role','dialog');pop.setAttribute('aria-label','选择'+label);pop.innerHTML=`<header>选择${label}</header><div class="filter-choices">${choices.map(x=>`<label><input type="checkbox" value="${esc(x.value)}" ${selected.includes(x.value)?'checked':''}><span>${esc(x.label)}</span></label>`).join('')||'<p>暂无可选分类</p>'}</div><footer>${id==='tag-filter'&&can('categories')?'<button type="button" class="filter-manage-tags">管理标签</button>':''}<button type="button" class="filter-clear">清除</button><button type="button" class="primary filter-save">保存</button></footer>`;wrap.append(pop);pop.querySelector('.filter-manage-tags')?.addEventListener('click',()=>{pop.hidePopover();manageTags();});trigger.setAttribute('aria-controls',pop.id);trigger.onclick=()=>{if(pop.matches(':popover-open')){pop.hidePopover();return;}pop.querySelectorAll('input').forEach(input=>input.checked=selected.includes(input.value));pop.showPopover();const box=trigger.getBoundingClientRect();pop.style.left=Math.max(8,Math.min(innerWidth-248,box.left))+'px';pop.style.top=Math.min(box.bottom+6,innerHeight-pop.offsetHeight-8)+'px';};pop.addEventListener('toggle',()=>trigger.setAttribute('aria-expanded',String(pop.matches(':popover-open'))));if(!multiple)pop.querySelectorAll('input').forEach(input=>input.onchange=()=>{if(input.checked)pop.querySelectorAll('input').forEach(other=>{if(other!==input)other.checked=false})});pop.querySelector('.filter-clear').onclick=()=>pop.querySelectorAll('input').forEach(input=>input.checked=false);pop.querySelector('.filter-save').onclick=()=>{const values=[...pop.querySelectorAll('input:checked')].map(x=>x.value);ui[key]=values.length?values.join('|'):base;pop.hidePopover();render();document.getElementById(id+'-trigger')?.focus();};}}

function setupProjectCards(root){cardResizeObserver?.disconnect();document.querySelector('.card-text-tooltip')?.remove();const fit=()=>root.querySelectorAll('.card-tag-space').forEach(box=>{const tags=[...box.querySelectorAll('.tag')],more=box.querySelector('.tag-overflow');tags.forEach(t=>t.hidden=false);more.hidden=true;if(!tags.length)return;const top=box.getBoundingClientRect().top;if(tags.some(t=>t.getBoundingClientRect().bottom>top+45)){more.hidden=false;for(let i=tags.length-1;i>=0;i--){tags[i].hidden=true;if(more.getBoundingClientRect().bottom<=top+45)break;}}});requestAnimationFrame(fit);cardResizeObserver=new ResizeObserver(fit);root.querySelectorAll('.project-card').forEach(card=>cardResizeObserver.observe(card));root.querySelectorAll('.project-card .projecttitle,.project-card [data-truncated-text]').forEach(el=>{el.removeAttribute('title');el.closest('.project-name-wrap')?.querySelector('.project-fullname')?.remove();let timer,tooltip;const hide=()=>{clearTimeout(timer);tooltip?.remove();tooltip=null;el.removeAttribute('aria-describedby');};const show=()=>{hide();if(el.scrollWidth<=el.clientWidth+1&&el.scrollHeight<=el.clientHeight+1)return;timer=setTimeout(()=>{if(!el.isConnected)return;tooltip=document.createElement('div');tooltip.className='card-text-tooltip';tooltip.setAttribute('role','tooltip');tooltip.id='card-tip-'+(++helpSequence);el.setAttribute('aria-describedby',tooltip.id);tooltip.textContent=el.textContent;document.body.append(tooltip);const r=el.getBoundingClientRect(),t=tooltip.getBoundingClientRect();tooltip.style.left=Math.max(8,Math.min(innerWidth-t.width-8,r.left))+'px';tooltip.style.top=Math.min(innerHeight-t.height-8,r.bottom+8)+'px';},500);};el.addEventListener('mouseenter',show);el.addEventListener('mouseleave',hide);el.addEventListener('focus',show);el.addEventListener('blur',hide);el.addEventListener('keydown',e=>{if(e.key==='Escape')hide()});});}
function setupSingleSelects(root){
 root.querySelectorAll('select:not([multiple]):not([hidden])').forEach(select=>{
  if(select.closest('.single-select'))return;
  const label=select.getAttribute('aria-label')||select.labels?.[0]?.childNodes[0]?.textContent.trim()||'选择选项';
  const wrap=document.createElement('span');wrap.className='single-select';select.before(wrap);wrap.append(select);select.hidden=true;
  const trigger=document.createElement('button');trigger.type='button';trigger.className='single-select-trigger';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-label',label);trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
  const pop=document.createElement('div');pop.className='single-select-menu';pop.id='single-options-'+(++helpSequence);pop.setAttribute('popover','auto');pop.setAttribute('role','listbox');pop.setAttribute('aria-label',label);trigger.setAttribute('aria-controls',pop.id);wrap.append(trigger,pop);
  const sync=()=>{trigger.disabled=select.disabled;trigger.innerHTML=`<span>${esc(select.selectedOptions[0]?.textContent||'请选择')}</span>${icon('chevron')}`;};sync();
  const open=()=>{if(select.disabled)return;pop.replaceChildren();[...select.options].forEach(option=>{const item=document.createElement('button');item.type='button';item.className='single-select-option';item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.selected));item.disabled=option.disabled;item.innerHTML=`<span class="single-select-check">${icon('check')}</span><span>${esc(option.textContent)}</span>`;item.onclick=e=>{e.preventDefault();select.value=option.value;pop.hidePopover();sync();select.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}));if(trigger.isConnected)trigger.focus();};pop.append(item);});pop.showPopover();const r=trigger.getBoundingClientRect();pop.style.width=Math.max(r.width,180)+'px';pop.style.maxWidth='calc(100vw - 16px)';pop.style.left=Math.max(8,Math.min(innerWidth-pop.offsetWidth-8,r.left))+'px';pop.style.top=Math.max(8,Math.min(innerHeight-pop.offsetHeight-8,r.bottom+6))+'px';};
  trigger.onclick=e=>{e.preventDefault();pop.matches(':popover-open')?pop.hidePopover():open();};
  trigger.onkeydown=e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();open();const items=[...pop.querySelectorAll('button:not(:disabled)')];(e.key==='End'?items.at(-1):pop.querySelector('[aria-selected=true]:not(:disabled)')||items[0])?.focus();}};
  pop.onkeydown=e=>{const items=[...pop.querySelectorAll('button:not(:disabled)')],index=items.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();items[e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();pop.hidePopover();trigger.focus();}if(e.key==='Tab')pop.hidePopover();};
  pop.addEventListener('toggle',()=>trigger.setAttribute('aria-expanded',String(pop.matches(':popover-open'))));select.addEventListener('change',sync);select.addEventListener('invalid',()=>trigger.focus());new MutationObserver(sync).observe(select,{attributes:true,childList:true,subtree:true});
 });
}

function usageProject(id){const p=o().projects.find(p=>p.id===id);if(!p||!can('usage')||!M.canAccessProject(s,p))return;modal('项目存储',`<h3>${esc(p.name)}</h3><div class="billing-fact"><span>当前存储</span><strong>${Number.isFinite(p.bytes)?fmt(p.bytes)+' GB':'—'}</strong></div><p class="billing-secondary">进入项目查看实验记录，或前往项目管理处理项目数据。</p>`,btn('进入项目','usageOpenProject','primary',`data-id="${esc(p.id)}"`));$('#modal').classList.add('role-drawer','billing-drawer');}
